using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;
public static class RoadCarBuilder{
 public static void Build(){Directory.CreateDirectory("Assets/NativeFullV1/Traffic");Directory.CreateDirectory("Assets/Resources/Traffic");string f="Assets/NativeFullV1/Traffic/CityCar.fbx";File.Copy("Assets/SourceModels/CityCar.fbx",f,true);AssetDatabase.ImportAsset(f);var importer=(ModelImporter)AssetImporter.GetAtPath(f);importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.isReadable=true;importer.SaveAndReimport();var model=PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(f))as GameObject;model.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);float front=model.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("Headlamp")).Average(t=>t.position.z);if(front<0)model.transform.rotation=Quaternion.Euler(0,180,0);var result=new GameObject("Compact city passenger car");var materials=new Dictionary<string,Material>();var groups=new Dictionary<Material,List<CombineInstance>>();foreach(var r in model.GetComponentsInChildren<MeshRenderer>()){var filter=r.GetComponent<MeshFilter>();for(int i=0;i<r.sharedMaterials.Length;i++){var old=r.sharedMaterials[i];if(!materials.TryGetValue(old.name,out var mat)){mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=old.name};mat.color=old.color;mat.SetFloat("_Smoothness",old.name.Contains("Glass")?.78f:old.name.Contains("Rubber")?.12f:.45f);mat.SetFloat("_Metallic",old.name.Contains("Alloy")?.8f:.18f);mat.enableInstancing=true;AssetDatabase.CreateAsset(mat,"Assets/NativeFullV1/Traffic/"+old.name+".mat");materials[old.name]=mat;}if(!groups.TryGetValue(mat,out var list)){list=new List<CombineInstance>();groups[mat]=list;}list.Add(new CombineInstance{mesh=filter.sharedMesh,subMeshIndex=i,transform=filter.transform.localToWorldMatrix});}}foreach(var group in groups){var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(group.Value.ToArray(),true,true);AssetDatabase.CreateAsset(mesh,"Assets/NativeFullV1/Traffic/"+group.Key.name+".asset");var o=new GameObject(group.Key.name,typeof(MeshFilter),typeof(MeshRenderer));o.transform.SetParent(result.transform);o.GetComponent<MeshFilter>().sharedMesh=mesh;o.GetComponent<MeshRenderer>().sharedMaterial=group.Key;}PrefabUtility.SaveAsPrefabAsset(result,"Assets/Resources/Traffic/CityCar.prefab");UnityEngine.Object.DestroyImmediate(result);UnityEngine.Object.DestroyImmediate(model);Debug.Log("CITY_CAR_PREFAB_PASS");}
}
